<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Snake</title>
<style>
  * {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  body {
    background: #222;
    color: #eee;
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 100vh;
    font-family: sans-serif;
  }

  #game-container {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 12px;
  }

  #snake {
    border: 2px solid #555;
    background: #111;
    display: block;
  }

  #score {
    font-size: 1.5rem;
    font-weight: bold;
    color: #ddd;
    text-align: center;
  }

  .buttons {
    display: flex;
    gap: 10px;
  }

  button {
    padding: 8px 16px;
    font-size: 1rem;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    background: #444;
    color: #eee;
    transition: background 0.2s;
  }

  button:hover {
    background: #666;
  }

  button:active {
    background: #555;
  }
</style>
</head>
<body>
<div id="game-container">
  <canvas id="snake"></canvas>
  <div id="score">Score: 0</div>
  <div class="buttons">
    <button id="start">Start</button>
    <button id="pause">Pause</button>
    <button id="reset">Reset</button>
  </div>
</div>

<script>
  (function() {
    // ---------- Board Settings ----------
    const CELL_SIZE = 20;
    const GRID_W = 20;      // default width in cells (≥10)
    const GRID_H = 20;      // default height in cells (≥10)
    const CANVAS_WIDTH = GRID_W * CELL_SIZE;   // 400px
    const CANVAS_HEIGHT = GRID_H * CELL_SIZE;  // 400px

    // ---------- DOM Elements ----------
    const canvas = document.getElementById('snake');
    const ctx = canvas.getContext('2d');
    const scoreDisplay = document.getElementById('score');
    const startBtn = document.getElementById('start');
    const pauseBtn = document.getElementById('pause');
    const resetBtn = document.getElementById('reset');

    // Set canvas dimensions (CSS + drawing buffer)
    canvas.width = CANVAS_WIDTH;
    canvas.height = CANVAS_HEIGHT;
    canvas.style.width = CANVAS_WIDTH + 'px';
    canvas.style.height = CANVAS_HEIGHT + 'px';

    // ---------- Game State ----------
    let gameState = {
      snake: [],
      direction: 'right',
      nextDir: null,
      food: [0, 0],
      alive: true,
      score: 0,
      grow: false,
      intervalId: null,
      running: false
    };

    // ---------- Helper Functions ----------
    function isOpposite(dir1, dir2) {
      const opp = { up: 'down', down: 'up', left: 'right', right: 'left' };
      return opp[dir1] === dir2;
    }

    // Get all cells not occupied by the snake
    function getFreeCells() {
      const occupied = new Set(gameState.snake.map(([x, y]) => `${x},${y}`));
      const free = [];
      for (let x = 0; x < GRID_W; x++) {
        for (let y = 0; y < GRID_H; y++) {
          if (!occupied.has(`${x},${y}`)) {
            free.push([x, y]);
          }
        }
      }
      return free;
    }

    // Place food randomly on a free cell
    function placeRandomFood() {
      const free = getFreeCells();
      if (free.length > 0) {
        const idx = Math.floor(Math.random() * free.length);
        gameState.food = free[idx];
      } else {
        // No free cells (snake filled board) – place something anyway (shouldn't happen)
        gameState.food = [0, 0];
      }
    }

    // ---------- Drawing ----------
    function redraw() {
      ctx.clearRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

      // Draw grid background (optional: light borders)
      ctx.fillStyle = '#1a1a1a';
      ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

      // Draw snake
      gameState.snake.forEach(([x, y], index) => {
        // Head is slightly brighter
        ctx.fillStyle = index === 0 ? '#4caf50' : '#2e7d32';
        ctx.fillRect(x * CELL_SIZE, y * CELL_SIZE, CELL_SIZE, CELL_SIZE);
        // Slight border
        ctx.strokeStyle = '#111';
        ctx.lineWidth = 1;
        ctx.strokeRect(x * CELL_SIZE, y * CELL_SIZE, CELL_SIZE, CELL_SIZE);
      });

      // Draw food
      const [fx, fy] = gameState.food;
      ctx.fillStyle = '#e53935';
      ctx.fillRect(fx * CELL_SIZE, fy * CELL_SIZE, CELL_SIZE, CELL_SIZE);
      ctx.strokeStyle = '#b71c1c';
      ctx.strokeRect(fx * CELL_SIZE, fy * CELL_SIZE, CELL_SIZE, CELL_SIZE);
    }

    function updateScoreDisplay() {
      scoreDisplay.textContent = 'Score: ' + gameState.score;
    }

    // ---------- Game Logic ----------
    function reset() {
      // Stop any auto-advance
      if (gameState.intervalId) {
        clearInterval(gameState.intervalId);
        gameState.intervalId = null;
        gameState.running = false;
      }

      // Initial snake: length 3, moving right, placed around middle
      const startX = Math.floor(GRID_W / 2);
      const startY = Math.floor(GRID_H / 2);
      gameState.snake = [
        [startX, startY],     // head
        [startX - 1, startY], // body
        [startX - 2, startY]  // tail
      ];
      gameState.direction = 'right';
      gameState.nextDir = null;
      gameState.alive = true;
      gameState.score = 0;
      gameState.grow = false;

      placeRandomFood();
      redraw();
      updateScoreDisplay();
    }

    function tick() {
      if (!gameState.alive) return;

      // Apply queued direction if not a 180° reversal
      let currentDir = gameState.direction;
      if (gameState.nextDir && !isOpposite(gameState.nextDir, currentDir)) {
        gameState.direction = gameState.nextDir;
        gameState.nextDir = null;
      }

      const dir = gameState.direction;
      const [headX, headY] = gameState.snake[0];
      let newHeadX, newHeadY;
      switch (dir) {
        case 'up':    newHeadX = headX; newHeadY = headY - 1; break;
        case 'down':  newHeadX = headX; newHeadY = headY + 1; break;
        case 'left':  newHeadX = headX - 1; newHeadY = headY; break;
        case 'right': newHeadX = headX + 1; newHeadY = headY; break;
        default: return;
      }

      // Wall collision
      if (newHeadX < 0 || newHeadX >= GRID_W || newHeadY < 0 || newHeadY >= GRID_H) {
        gameState.alive = false;
        // Stop auto-advance on death
        if (gameState.intervalId) {
          clearInterval(gameState.intervalId);
          gameState.intervalId = null;
          gameState.running = false;
        }
        redraw();
        return;
      }

      // Self collision: check newHead against body (excluding the tail if not growing)
      const tailWillBeRemoved = !gameState.grow;
      let bodyToCheck;
      if (tailWillBeRemoved) {
        // ignore the last element (tail) because it will be removed
        bodyToCheck = gameState.snake.slice(0, -1);
      } else {
        bodyToCheck = gameState.snake; // include everything
      }

      if (bodyToCheck.some(([x, y]) => x === newHeadX && y === newHeadY)) {
        gameState.alive = false;
        if (gameState.intervalId) {
          clearInterval(gameState.intervalId);
          gameState.intervalId = null;
          gameState.running = false;
        }
        redraw();
        return;
      }

      // Move: add new head
      gameState.snake.unshift([newHeadX, newHeadY]);

      // Check if food eaten
      if (newHeadX === gameState.food[0] && newHeadY === gameState.food[1]) {
        gameState.score++;
        gameState.grow = true;   // will keep tail this move
        placeRandomFood();       // new food on a random free cell
        updateScoreDisplay();
      }

      // Tail removal or growth handling
      if (gameState.grow) {
        gameState.grow = false;
        // do not remove tail
      } else {
        gameState.snake.pop();   // remove tail
      }

      redraw();
    }

    function setDir(direction) {
      // Only queue if the snake is alive (but can still be queued even if dead,
      // but then it won't be applied until tick is called after reset).
      // The grading requirement: ignore 180° reversal.
      const currentDir = gameState.direction;
      if (isOpposite(direction, currentDir)) {
        return; // ignored
      }
      gameState.nextDir = direction;
    }

    function setFood(x, y) {
      gameState.food = [x, y];
      redraw();
    }

    // ---------- Auto-Advance Control ----------
    function startGame() {
      if (!gameState.running && gameState.alive) {
        gameState.intervalId = setInterval(tick, 150);
        gameState.running = true;
      }
    }

    function pauseGame() {
      if (gameState.intervalId) {
        clearInterval(gameState.intervalId);
        gameState.intervalId = null;
        gameState.running = false;
      }
    }

    function resetGame() {
      pauseGame();
      reset();
    }

    // ---------- Event Listeners ----------
    startBtn.addEventListener('click', startGame);
    pauseBtn.addEventListener('click', pauseGame);
    resetBtn.addEventListener('click', resetGame);

    window.addEventListener('keydown', (e) => {
      // Prevent arrow keys from scrolling
      if (e.key.startsWith('Arrow')) {
        e.preventDefault();
      }
      switch (e.key) {
        case 'ArrowUp':    setDir('up');    break;
        case 'ArrowDown':  setDir('down');  break;
        case 'ArrowLeft':  setDir('left');  break;
        case 'ArrowRight': setDir('right'); break;
      }
    });

    // ---------- Public API ----------
    window.game = {
      w: GRID_W,
      h: GRID_H,
      reset: resetGame,
      tick: tick,
      setDir: setDir,
      setFood: setFood,
      snake: () => gameState.snake.map(([x, y]) => [x, y]), // return a defensively shallow copy
      food: () => [...gameState.food],
      alive: () => gameState.alive,
      score: () => gameState.score
    };

    // Initialise game on load
    reset();
  })();
</script>
</body>
</html>
